using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Text.Json;
using CapFrameX.Video.Overlay;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace CapFrameX.Video.Test;

/// <summary>
/// Differential tests: the C# <see cref="HudMetrics"/> port must reproduce
/// fps-analyzer's HUD metric stage bit-for-bit (float64). Goldens were
/// generated by the real Python code path (scratch/gen_goldens.py) on the
/// committed test clips; see TestAssets/goldens/clip_*.json.
/// </summary>
[TestClass]
public sealed class HudMetricsGoldenTests
{
    private static string GoldenDir => Path.Combine("TestAssets", "goldens");

    [DataTestMethod]
    [DataRow("clip_30fps")]
    [DataRow("clip_60fps")]
    [DataRow("clip_vfr")]
    public void MetricsMatchPythonReference(string clip)
    {
        var json = File.ReadAllText(Path.Combine(GoldenDir, clip + ".json"));
        using var doc = JsonDocument.Parse(json);
        var root = doc.RootElement;

        var pts = new List<double>();
        foreach (var e in root.GetProperty("pts").EnumerateArray()) pts.Add(e.GetDouble());
        double declared = root.GetProperty("declared_fps").GetDouble();

        var res = HudMetrics.Compute(pts, declared);

        int n = root.GetProperty("n").GetInt32();
        Assert.AreEqual(n, pts.Count, "n mismatch");
        Assert.AreEqual(root.GetProperty("base").GetDouble(), res.BaseMs,
            "base ms mismatch");
        Assert.AreEqual(root.GetProperty("base_fps").GetDouble(), res.BaseFps,
            "base fps mismatch");
        Assert.AreEqual(root.GetProperty("win").GetInt32(), res.Window, "win mismatch");
        Assert.AreEqual(root.GetProperty("k").GetInt32(), res.K, "k mismatch");
        Assert.AreEqual(root.GetProperty("r").GetInt32(), res.R, "r mismatch");

        // stutter_set: sorted indices → bool[]
        var goldenStutter = new bool[n];
        foreach (var e in root.GetProperty("stutter_set").EnumerateArray())
            goldenStutter[e.GetInt32()] = true;
        Assert.IsTrue(SequenceEqual(goldenStutter, res.StutterSet), "stutter_set mismatch");

        var goldenBlk = new bool[root.GetProperty("stutter_blk").GetArrayLength()];
        int bi = 0;
        foreach (var e in root.GetProperty("stutter_blk").EnumerateArray())
            goldenBlk[bi++] = e.GetInt32() != 0;
        Assert.IsTrue(SequenceEqual(goldenBlk, res.StutterBlockFlags), "stutter_blk mismatch");

        BitExactCompare(root.GetProperty("dt_all"), res.DtAll, "dt_all", clip);
        BitExactCompare(root.GetProperty("fps_disp"), res.FpsDisplay, "fps_disp", clip);
        BitExactCompare(root.GetProperty("dt_disp"), res.DtDisplay, "dt_disp", clip);
    }

    /// <summary>
    /// Element-wise bit-exact comparison: the goldens were dumped via
    /// Python's json (float repr), which round-trips float64 exactly, so any
    /// deviation is a real math discrepancy in the port.
    /// </summary>
    private static void BitExactCompare(JsonElement arr, IReadOnlyList<double> actual,
        string name, string clip)
    {
        int len = arr.GetArrayLength();
        Assert.AreEqual(len, actual.Count, $"{name}: length");
        int firstBad = -1;
        double maxAbsDiff = 0;
        for (int i = 0; i < len; i++)
        {
            double expected = arr[i].GetDouble();
            if (!double.Equals(expected, actual[i]))
            {
                if (firstBad < 0) firstBad = i;
                maxAbsDiff = Math.Max(maxAbsDiff, Math.Abs(expected - actual[i]));
            }
        }
        if (firstBad >= 0)
            Assert.Fail($"{clip}/{name}: first mismatch at index {firstBad}, " +
                        $"expected {expectedRepr(arr, firstBad)}, got {actual[firstBad]:R}, " +
                        $"max abs diff {maxAbsDiff:E3}");
    }

    private static string expectedRepr(JsonElement arr, int i) =>
        arr[i].GetDouble().ToString("R", CultureInfo.InvariantCulture);

    private static bool SequenceEqual(IReadOnlyList<bool> expected, IReadOnlyList<bool> actual)
    {
        if (expected.Count != actual.Count) return false;
        for (int i = 0; i < expected.Count; i++)
            if (expected[i] != actual[i]) return false;
        return true;
    }

    [TestMethod]
    public void RequiresAtLeastTwoFrames()
    {
        Assert.Throws<ArgumentException>(() => HudMetrics.Compute(new[] { 0.0 }, 30.0));
        Assert.Throws<ArgumentException>(() => HudMetrics.Compute(new double[0], 30.0));
    }
}
